/bin/zsh -lc "python3 -B - <<'PY'
from backend import Backend, Duplicate
from service import save

backend = Backend()
created = save(backend, 'key', 'original')['created']
print(f'direct creation: {created"'!r}; literal True: {created is True}'"')
try:
    save(backend, 'key', 'replacement')
except Duplicate:
    print('direct duplicate: Duplicate propagates')
print(f'original retained: {backend.rows[\"key\"] == \"original\"}')
class Offline:
    def put(self, key, value):
        raise OSError('offline')
try:
    save(Offline(), 'key', 'value')
except OSError:
    print('direct operational failure: OSError propagates')
PY"

